<?php
declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';require_role(['admin']);
if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Method Not Allowed');}verify_csrf();$id=max(0,(int)($_POST['id']??0));$q=db()->prepare('SELECT full_name,national_id FROM personnel WHERE id=?');$q->execute([$id]);$p=$q->fetch();if(!$p)redirect('personnel.php');$q=db()->prepare('SELECT COUNT(*) FROM assets WHERE personnel_id=?');$q->execute([$id]);$assetCount=(int)$q->fetchColumn();$db=db();$db->beginTransaction();try{$db->prepare('DELETE FROM personnel WHERE id=?')->execute([$id]);$db->commit();audit('personnel_deleted','personnel',(string)$id,['full_name'=>$p['full_name'],'national_id'=>$p['national_id'],'detached_assets'=>$assetCount]);flash('success','پرسنل حذف شد. '.($assetCount?'مسئولیت '.$assetCount.' تجهیز نیز خالی شد.':''));}catch(Throwable $e){if($db->inTransaction())$db->rollBack();flash('danger','حذف انجام نشد: '.$e->getMessage());}redirect('personnel.php');
